229	        if min == max {
230	            eco_format!("{} requires version {}", validator.as_str(), min.as_str())
231	        } else {
232	            eco_format!(
233	                "{} requires a version between {} and {}",
234	                validator.as_str(),
235	                min.as_str(),
236	                max.as_str()
237	            )
238	        }
239	    } else {
240	        eco_format!("{} requires at least {}", validator.as_str(), max.as_str())
241	    }
242	}
