175	/// A state allowing us to keep track of transforms and container sizes,
176	/// which is mainly needed to resolve gradients and patterns correctly.
177	#[derive(Debug, Clone)]
178	pub(crate) struct State {
179	    /// The current transform.
180	    transform: Transform,
181	    /// The transform of first hard frame in the hierarchy.
182	    container_transform: Transform,
183	    /// The size of the first hard frame in the hierarchy.
184	    container_size: Size,
185	}
186	
187	impl State {
188	    /// Creates a new, clean state for a given `size`.
189	    fn new(size: Size) -> Self {
190	        Self {
191	            transform: Transform::identity(),
192	            container_transform: Transform::identity(),
193	            container_size: size,
194	        }
195	    }
196	
197	    pub(crate) fn register_container(&mut self, size: Size) {
198	        self.container_transform = self.transform;
199	        self.container_size = size;
200	    }
201	
202	    pub(crate) fn pre_concat(&mut self, transform: Transform) {
203	        self.transform = self.transform.pre_concat(transform);
204	    }
205	
206	    pub(crate) fn transform(&self) -> Transform {
207	        self.transform
208	    }
209	
210	    pub(crate) fn container_transform(&self) -> Transform {
211	        self.container_transform
212	    }
213	
214	    pub(crate) fn container_size(&self) -> Size {
215	        self.container_size
216	    }
217	}
