229	impl FrameContext {
230	    pub(crate) fn new(page_idx: Option<usize>, size: Size) -> Self {
231	        Self {
232	            page_idx,
233	            states: vec![State::new(size)],
234	            link_annotations: IndexMap::default(),
235	        }
236	    }
237	
238	    pub(crate) fn push(&mut self) {
239	        self.states.push(self.states.last().unwrap().clone());
240	    }
241	
242	    pub(crate) fn pop(&mut self) {
243	        self.states.pop();
244	    }
245	
246	    pub(crate) fn state(&self) -> &State {
247	        self.states.last().unwrap()
248	    }
249	
250	    pub(crate) fn state_mut(&mut self) -> &mut State {
251	        self.states.last_mut().unwrap()
252	    }
253	
254	    pub(crate) fn page_size(&self) -> Option<Size> {
255	        self.page_idx
256	            .is_some()
257	            .then_some(self.states.first().unwrap().container_size)
258	    }
259	
260	    pub(crate) fn get_link_annotation(
261	        &mut self,
262	        id: GroupId,
263	    ) -> Option<&mut LinkAnnotation> {
264	        self.link_annotations.get_mut(&id)?.last_mut()
265	    }
266	
267	    pub(crate) fn push_link_annotation(
268	        &mut self,
269	        id: GroupId,
270	        annotation: LinkAnnotation,
271	    ) {
272	        let annotations = self.link_annotations.entry(id).or_default();
273	        annotations.push(annotation);
274	    }
275	}
