432	/// Finish a krilla document and handle export errors.
433	#[typst_macros::time(name = "finish export")]
434	fn finish(
435	    document: Document,
436	    gc: GlobalContext,
437	    configuration: Configuration,
438	) -> SourceResult<Vec<u8>> {
439	    match document.finish() {
440	        Ok(r) => Ok(r),
441	        Err(e) => match e {
442	            KrillaError::Font(f, err) => {
443	                bail!(
444	                    Span::detached(),
445	                    "failed to process {} ({err})",
446	                    display_font(gc.fonts_backward.get(&f));
447	                    hint: "make sure the font is valid";
448	                    hint: "the used font might be unsupported by Typst";
449	                );
450	            }
451	            KrillaError::Validation(ve) => {
452	                let errors = ve
453	                    .iter()
454	                    .map(|(e, validators)| {
455	                        convert_error(&gc, *validators, e, configuration.version())
456	                    })
457	                    .collect::<EcoVec<_>>();
458	                Err(errors)
459	            }
460	            KrillaError::Image(_, loc, err) => {
461	                let span = to_span(loc);
462	                bail!(span, "failed to process image ({err})");
463	            }
464	            KrillaError::SixteenBitImage(image, _) => {
465	                let span = &gc.image_to_spans[&image];
466	                bail!(
467	                    *span, "16 bit images are not supported in this export mode";
468	                    hint: "convert the image to 8 bit instead";
469	                )
470	            }
471	            KrillaError::Pdf(_, e, loc) => {
472	                let span = to_span(loc);
473	                match e {
474	                    // We already validated in `typst-library` that the page index is valid.
475	                    PdfError::InvalidPage(_) => bail!(
476	                        span,
477	                        "invalid page number for PDF file";
478	                        hint: "please report this as a bug";
479	                    ),
480	                    PdfError::VersionMismatch(v) => {
481	                        let pdf_ver = v.as_str();
482	                        let config_ver = configuration.version();
483	                        let cur_ver = config_ver.as_str();
484	                        bail!(span,
485	                            "the version of the PDF is too high";
486	                            hint: "the current export target is {cur_ver}, while the PDF \
487	                                   has version {pdf_ver}";
488	                            hint: "raise the export target to {pdf_ver} or higher";
489	                            hint: "or preprocess the PDF to convert it to a lower version";
490	                        );
491	                    }
492	                }
493	            }
494	            KrillaError::DuplicateTagId(_, loc) => {
495	                let span = to_span(loc);
496	                bail!(span,
497	                    "duplicate tag id";
498	                    hint: "please report this as a bug";
499	                );
500	            }
501	            KrillaError::UnknownTagId(_, loc) => {
502	                let span = to_span(loc);
503	                bail!(span,
504	                    "unknown tag id";
505	                    hint: "please report this as a bug";
506	                );
507	            }
508	            KrillaError::DuplicateNamedDestination(_) => {
509	                bail!(Span::detached(),
510	                    "duplicate named destination";
511	                    hint: "please report this as a bug";
512	                );
513	            }
514	            KrillaError::Limit(LimitError::TooLongArray) => bail!(
515	                Span::detached(),
516	                "a PDF array is longer than 8191 elements";
517	                hint: "set the PDF version to PDF 1.5 or later";
518	                hint: "this can happen if you have a very long text in a single line";
519	            ),
520	            KrillaError::Limit(LimitError::TooLongDictionary) => bail!(
521	                Span::detached(),
522	                "a PDF dictionary has more than 4095 entries";
523	                hint: "set the PDF version to PDF 1.5 or later";
524	                hint: "alternatively, try reducing the complexity of your document";
525	            ),
526	            KrillaError::Limit(LimitError::TooLargeFloat) => bail!(
527	                Span::detached(),
528	                "a PDF floating point number is larger than the allowed limit";
529	                hint: "set the PDF version to PDF 1.5 or later";
530	            ),
531	        },
532	    }
533	}
